-- =============================================================================
-- 0026 — Case-law discovery seed: Google News per GCC country, court/ruling
-- content ("آخر القضايا")
--
-- Six new discovery pseudo-source rows, one per GCC country (SA/AE/KW/QA/BH/
-- OM — never GCC itself; a case belongs to the country it happened in, per
-- the same country-registry rule the Publishing Gate already enforces).
-- Parallel to, and fully independent of, the six legal-update discovery
-- sources seeded in 0022: same architecture (source_type = 'discovery_engine',
-- ingestion_mode = 'discovery'), but a different, court/ruling-specific
-- phrase set (lib/discovery/discovery.ts CASE_LAW_PHRASES /
-- buildCaseLawFeedUrl) instead of the legislative one. Kept as separate rows
-- rather than merged into the existing six feeds so each can be tuned,
-- monitored, and (if ever needed) disabled independently, without touching
-- the already-fixed and live-verified legal-update feeds.
--
-- base_url is Google News' own WEB search results page for the same
-- case-law query (/search?q=...), NOT a copy of the legislative feed's
-- generic country homepage (/?gl=XX) and NOT the RSS endpoint (that's
-- feed_url, /rss/search?q=...). This is a genuine, resolvable, distinct
-- canonical URL per row — not a synthetic differentiator — and is what
-- fixed the first attempt at this migration, which reused the legislative
-- feed's base_url verbatim and hit sources_base_url_key (that unique index,
-- and sources_feed_url_key, are correct and were NOT touched).
--
-- Oman's query uses 'سلطنة عمان' (Sultanate of Oman), the same
-- Amman-disambiguated form used for the legal-update feed after the
-- Oman/Amman misclassification fix — this seed never reintroduces the bare,
-- ambiguous 'عمان'.
--
-- No item from these sources is ever inserted into legal_updates without
-- first passing AI legal classification (tightened for case-news quality —
-- see n8n/prompts/classify-legal-update.md) and the Publishing Gate, same as
-- every other source.
-- =============================================================================

insert into public.sources
  (country, authority_ar, authority_en, source_type, ingestion_mode, base_url, active,
   parser_type, feed_url, parser_config, allowed_domains, priority, poll_interval_minutes,
   config_status, confidence, verification_method, notes)
